package dev.admutium.techmod.test;
import dev.admutium.techmod.suit.*;import dev.admutium.techmod.machine.*;import dev.admutium.techmod.energy.Energy;import dev.admutium.techmod.client.suit.*;
import net.fabricmc.fabric.api.client.gametest.v1.*;import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;import net.minecraft.client.CameraType;import net.minecraft.client.gui.screens.worldselection.WorldCreationUiState;import net.minecraft.core.*;import net.minecraft.world.item.*;import net.minecraft.world.level.block.Blocks;
public final class SuitFunctionalVisualTest implements FabricClientGameTest {
 @Override public void runTest(ClientGameTestContext c){try(var sp=c.worldBuilder().adjustSettings(s->s.setGameMode(WorldCreationUiState.SelectedGameMode.CREATIVE)).create()){
  c.runOnClient(client->{SuitPreview.setEnabled(false);client.options.setCameraType(CameraType.FIRST_PERSON);});
  sp.getServer().runCommand("gamerule minecraft:send_command_feedback false");sp.getServer().runCommand("fill -16 2 -16 16 2 16 minecraft:smooth_stone");sp.getServer().runCommand("time set 6000");sp.getServer().runCommand("tp @a 0 3 0 180 0");c.getInput().resizeWindow(1280,800);sp.getConnection().waitForChunksRender();
  sp.getServer().runOnServer(server->{var p=sp.getConnection().getServerPlayer();p.getInventory().clearContent();var level=p.level();var pos=new BlockPos(0,3,-3);level.setBlockAndUpdate(pos,Machines.BLOCKS.get(MachineKind.STATION).defaultBlockState().setValue(MachineBlock.FACING,Direction.SOUTH));level.setBlockAndUpdate(pos.north(),Machines.BLOCKS.get(MachineKind.CREATIVE_SOURCE).defaultBlockState().setValue(MachineBlock.FACING,Direction.NORTH));p.openMenu((MachineBlockEntity)level.getBlockEntity(pos));});c.waitForScreen(SuitStationScreen.class);c.waitTicks(8);c.takeScreenshot("kontur-suit-station-empty");
  c.runOnClient(client->{var menu=client.player.containerMenu;net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new SuitPackets.Action("create","",menu.containerId));});c.waitTicks(5);c.runOnClient(client->{net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.send(new SuitPackets.Action("all","",client.player.containerMenu.containerId));});c.waitFor(client->SuitClient.data.level(SuitUpgrade.MINING)==20);c.takeScreenshot("kontur-suit-station-upgrades");
  sp.getServer().runOnServer(server->{var p=sp.getConnection().getServerPlayer();var menu=(SuitStationMenu)p.containerMenu;var s=menu.subject();if(s.energy<=0)throw new AssertionError("Station did not charge suit from creative source");s.energy=20000*Energy.UNIT;s.flush();menu.action("equip","");});c.waitFor(client->!Suits.worn(client.player).isEmpty());c.setScreen(()->null);c.waitTicks(10);c.takeScreenshot("kontur-suit-functional-hud");
  c.getInput().pressKey(258);c.waitForScreen(SuitRadialScreen.class);c.waitTicks(4);c.takeScreenshot("kontur-suit-systems-radial");c.setScreen(()->null);
  c.runOnClient(client->{SuitClient.action("toggle","run");SuitClient.action("toggle","ore_scan");SuitClient.action("toggle","night");});
  sp.getServer().runOnServer(server->{var p=sp.getConnection().getServerPlayer();var s=Suits.session(p);s.nutrients=140;s.flush();p.getInventory().setItem(0,new ItemStack(Items.DIAMOND,17));var l=p.level();l.setBlockAndUpdate(new BlockPos(0,4,-7),Blocks.DIAMOND_ORE.defaultBlockState());l.setBlockAndUpdate(new BlockPos(0,4,-6),Blocks.STONE.defaultBlockState());});c.waitTicks(50);c.takeScreenshot("kontur-suit-ore-scanner");
  c.getInput().pressKey(options->options.keyInventory);c.waitForScreen(SuitInventoryScreen.class);c.waitTicks(5);c.runOnClient(client->{if(SuitClient.wornData().contents().nutrients()!=140)throw new AssertionError("Opening inventory rewound suit data");});c.takeScreenshot("kontur-suit-expanded-inventory");c.setScreen(()->null);
  c.runOnClient(client->SuitClient.action("toggle","flight"));c.waitFor(client->SuitClient.wornData().on("flight_jet"));c.runOnClient(client->SuitClient.action("toggle","flight"));c.waitFor(client->SuitClient.wornData().on("flight_elytra"));c.runOnClient(client->{if(!net.minecraft.world.entity.LivingEntity.canGlideUsing(Suits.worn(client.player),net.minecraft.world.entity.EquipmentSlot.CHEST))throw new AssertionError("Actual client item cannot start elytra flight");SuitClient.action("toggle","flight");client.options.setCameraType(CameraType.THIRD_PERSON_FRONT);});c.waitFor(client->SuitClient.wornData().on("flight_gravity"));c.waitTicks(12);c.runOnClient(client->{var visual=(net.minecraft.client.renderer.entity.state.AvatarRenderState)client.getEntityRenderDispatcher().extractEntity(client.player,1);var d=visual.getDataOrDefault(SuitClient.VISUAL,SuitData.EMPTY);if(!d.on("flight_gravity"))throw new AssertionError("Render state lost gravity wings: "+d.active());});c.takeScreenshot("kontur-suit-gravity-mode");c.runOnClient(client->client.options.setCameraType(CameraType.THIRD_PERSON_BACK));c.waitTicks(5);c.takeScreenshot("kontur-suit-gravity-back-functional");
  sp.getServer().runOnServer(server->{var p=sp.getConnection().getServerPlayer();var s=Suits.session(p);if(!s.on("flight_gravity")||!p.getAbilities().flying)throw new AssertionError("Gravity mode not active");if(s.rates[0]<=0)throw new AssertionError("Flight energy not reported");if(p.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.HEAD).isEmpty()==false)throw new AssertionError("Extra armor equipped");});
  c.runOnClient(client->{SuitClient.action("toggle","cloak");client.options.setCameraType(CameraType.THIRD_PERSON_FRONT);});c.waitTicks(10);c.takeScreenshot("kontur-suit-camouflage");c.runOnClient(client->{SuitClient.action("toggle","cloak");SuitClient.action("toggle","flight");client.options.setCameraType(CameraType.FIRST_PERSON);});c.waitTicks(6);c.takeScreenshot("kontur-suit-vanilla-hand-functional");
 }}
}
